-- COOKIWIKI : exécuter dans le projet Supabase Cookiwiki, jamais Mealio.
-- 35 recettes sur les 56 : sauvegarde avant modification ; estimations signalées.
-- Une recette déjà modifiée depuis l'export sera conservée et signalée SKIPPED.
BEGIN;
SELECT pg_advisory_xact_lock(hashtext('mealio-cookiwiki-v1212'));
CREATE TABLE IF NOT EXISTS public.mealio_recipe_change_log (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recipe_id uuid NOT NULL,
 operation text NOT NULL, previous_ingredients jsonb, next_ingredients jsonb,
 username text, created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.mealio_recipe_change_log ADD COLUMN IF NOT EXISTS previous_structure jsonb;
ALTER TABLE public.mealio_recipe_change_log ADD COLUMN IF NOT EXISTS next_structure jsonb;
ALTER TABLE public.mealio_recipe_change_log ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX IF NOT EXISTS mealio_recipe_seed_unique
 ON public.mealio_recipe_change_log(recipe_id,operation) WHERE operation='seed-v1.2.12';
CREATE TABLE IF NOT EXISTS public.mealio_recipe_structures (
 recipe_id uuid PRIMARY KEY REFERENCES public.recipes(id) ON DELETE CASCADE,
 structure jsonb NOT NULL, ingredients_snapshot jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.mealio_recipe_structures ENABLE ROW LEVEL SECURITY;
GRANT SELECT ON public.mealio_recipe_structures,public.mealio_recipe_change_log TO service_role;
-- Chaque ingrédient visible par Cookiwiki reste plat (name/qty/unit).
CREATE OR REPLACE FUNCTION public.mealio_flatten_recipe_lines(p_lines jsonb,p_depth integer DEFAULT 0)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public,pg_temp AS $flat$
DECLARE item jsonb; result jsonb:='[]'::jsonb; expanded jsonb; index_choice integer;
BEGIN
 IF p_depth>5 OR jsonb_typeof(p_lines)<>'array' THEN RAISE EXCEPTION 'INGREDIENTS_INVALID'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_lines) LOOP
  IF item->>'exclude_from_shopping'='true' OR (item->>'optional'='true' AND coalesce(item->>'included','false')<>'true') THEN CONTINUE; END IF;
  IF item ? 'components' THEN expanded:=public.mealio_flatten_recipe_lines(item->'components',p_depth+1);
  ELSIF item ? 'alternatives' THEN
   IF item->>'selected' IS NULL THEN expanded:=jsonb_build_array(jsonb_build_object('name',item->>'name','qty',0,'unit',''));
   ELSE index_choice:=(item->>'selected')::integer;IF index_choice<0 OR index_choice>=jsonb_array_length(item->'alternatives') THEN RAISE EXCEPTION 'CHOICE_INVALID'; END IF;
    expanded:=public.mealio_flatten_recipe_lines(jsonb_build_array((item->'alternatives')->index_choice),p_depth+1);END IF;
  ELSE expanded:=jsonb_build_array(item-'components'-'alternatives'-'selected');END IF;
  result:=result||expanded;
 END LOOP;
 RETURN result;
END $flat$;
REVOKE ALL ON FUNCTION public.mealio_flatten_recipe_lines(jsonb,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.mealio_flatten_recipe_lines(jsonb,integer) TO service_role;
CREATE OR REPLACE FUNCTION public.mealio_update_recipe_ingredients(
 p_recipe_id uuid,p_expected jsonb,p_next jsonb,p_username text
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $fn$
DECLARE current_recipe public.recipes%ROWTYPE; current_structure jsonb; flattened jsonb;
BEGIN
 IF p_next IS NULL OR jsonb_typeof(p_next)<>'array' THEN RAISE EXCEPTION 'INGREDIENTS_INVALID'; END IF;
 SELECT * INTO current_recipe FROM public.recipes WHERE id=p_recipe_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'RECIPE_NOT_FOUND'; END IF;
 SELECT structure INTO current_structure FROM public.mealio_recipe_structures WHERE recipe_id=p_recipe_id FOR UPDATE;
 IF coalesce(current_recipe.ingredients::jsonb,'null'::jsonb) IS DISTINCT FROM coalesce(p_expected->'ingredients','null'::jsonb) OR coalesce(current_structure,'null'::jsonb) IS DISTINCT FROM coalesce(p_expected->'structure','null'::jsonb)
 THEN RAISE EXCEPTION 'RECIPE_CONFLICT'; END IF;
 flattened:=public.mealio_flatten_recipe_lines(p_next);
 INSERT INTO public.mealio_recipe_change_log(recipe_id,operation,previous_ingredients,next_ingredients,previous_structure,next_structure,username)
 VALUES(p_recipe_id,'manual',current_recipe.ingredients::jsonb,flattened,current_structure,p_next,p_username);
 UPDATE public.recipes SET ingredients=flattened WHERE id=p_recipe_id;
 INSERT INTO public.mealio_recipe_structures(recipe_id,structure,ingredients_snapshot) VALUES(p_recipe_id,p_next,flattened) ON CONFLICT(recipe_id) DO UPDATE SET structure=excluded.structure,ingredients_snapshot=excluded.ingredients_snapshot,updated_at=now();
 RETURN jsonb_build_object('id',p_recipe_id,'ingredients',p_next);
END $fn$;
REVOKE ALL ON FUNCTION public.mealio_update_recipe_ingredients(uuid,jsonb,jsonb,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.mealio_update_recipe_ingredients(uuid,jsonb,jsonb,text) TO service_role;
