 LOOP
  IF EXISTS(SELECT 1 FROM public.mealio_recipe_change_log WHERE recipe_id=(proposal->>'id')::uuid AND operation='seed-v1.2.12') THEN CONTINUE; END IF;
  SELECT ingredients::jsonb INTO current_ingredients FROM public.recipes WHERE id=(proposal->>'id')::uuid FOR UPDATE;
  IF NOT FOUND OR current_ingredients IS DISTINCT FROM proposal->'expected' THEN
   skipped:=skipped+1;RAISE NOTICE 'SKIPPED : % (%) : absente ou modifiée depuis l’export.',proposal->>'title',proposal->>'id';CONTINUE;
  END IF;
  INSERT INTO public.mealio_recipe_change_log(recipe_id,operation,previous_ingredients,next_ingredients,next_structure,username)
   VALUES((proposal->>'id')::uuid,'seed-v1.2.12',current_ingredients,public.mealio_flatten_recipe_lines(proposal->'ingredients'),proposal->'ingredients','seed');
  UPDATE public.recipes SET ingredients=public.mealio_flatten_recipe_lines(proposal->'ingredients') WHERE id=(proposal->>'id')::uuid;
  INSERT INTO public.mealio_recipe_structures(recipe_id,structure,ingredients_snapshot) VALUES((proposal->>'id')::uuid,proposal->'ingredients',public.mealio_flatten_recipe_lines(proposal->'ingredients')) ON CONFLICT(recipe_id) DO UPDATE SET structure=excluded.structure,ingredients_snapshot=excluded.ingredients_snapshot,updated_at=now();
  changed:=changed+1;
 END LOOP;
 RAISE NOTICE 'Mealio v1.2.12 : % recettes modifiées ; % conservées à vérifier.',changed,skipped;
END $seed$;
COMMIT;
SELECT r.id,r.title,l.created_at FROM public.mealio_recipe_change_log l JOIN public.recipes r ON r.id=l.recipe_id WHERE l.operation='seed-v1.2.12' ORDER BY r.title;
